layouts.css:
body, #adm-sticker, #adm-sticker * {
  color: #000 !important;
}
/* ====== CONTAINER FULL ====== */
.container {
  display: flex;
  justify-content: space-between; 
  align-items: flex-start;
  width: 100%;          
  margin: 0;
  padding: 0;
  box-sizing: border-box;
  overflow-x: hidden;
}

/* ====== CỘT TRÁI (TEM) ====== */
.container-left {
  flex: 1;
  display: flex;
  justify-content: center;
}

/* ====== GRID 2×3 (màn hình) ====== */
#adm-sticker {
  display: grid !important;
  grid-template-columns: repeat(2, 93mm) !important;
  gap: 10px 10px !important;
  justify-content: center !important;
  text-align: center !important;
}

/* ====== TEM ====== */
#adm-sticker .frm {
  width: 93mm !important;
  height: 93mm !important;
  position: relative !important;
  background-image: url("/assets/ncn-store-tools/sales/0065a4735bed1d69b840.png") !important;
  background-position: center !important;
  background-size: contain !important;
  background-repeat: no-repeat !important;
  overflow: hidden !important;
}

/* ====== RESET ====== */
#adm-sticker .frm div {
  position: absolute !important;
  left: 0;
  width: 100% !important;
  margin: 0 !important;
  padding: 0 !important;
  text-align: center !important;
  background: transparent !important;
  white-space: nowrap !important;
  cursor: text !important;
}

/* TÊN SẢN PHẨM */
#adm-sticker .frm .name {
  font-family: 'utm-cafeta', Arial, sans-serif !important;
  font-size: 20px !important;
  top: 98px;
  height: 30px;
  line-height: 30px;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

/* GIÁ CŨ */
#adm-sticker .frm .old {
  font-family: 'Bai Jamjuree', sans-serif !important;
  font-size: 40px !important;
  top: 131px;
  text-decoration: line-through !important;
  height: 35px;
  line-height: 35px;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
  display: inline-block;
}
#adm-sticker .frm .old::before,
#adm-sticker .frm .old::after {
  content: " ";
  display: inline-block;
  width: 12px;
}

/* GIÁ MỚI */
#adm-sticker .frm .new {
  font-family: 'utm-avo', Arial, sans-serif !important;
  font-size: 50px !important;
  font-weight: 700 !important;
  top: 168px;
  height: 50px;
  line-height: 50px;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

/* EXTRA1 */
#adm-sticker .frm .extra1 {
  font-family: 'Utm-colossalis', Arial, sans-serif !important;
  font-size: 23px !important;
  top: 225px;
  height: 30px;
  line-height: 31px;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

/* EXTRA2 */
#adm-sticker .frm .extra2 {
  font-family: 'Utm-colossalis', Arial, sans-serif !important;
  font-size: 39px !important;
  top: 255px;
  height: 45px;
  line-height: 50px;
  white-space: nowrap !important;
  overflow: hidden !important;
  text-overflow: ellipsis !important;
}

/* ====== CỘT PHẢI (HƯỚNG DẪN) ====== */
.container-right {
  width: 330px;
  font-family: 'Bai Jamjuree', sans-serif !important;
  font-size: 15px;
  color: #000 !important;
  background: #DDDDDD;
  padding: 16px;
  box-sizing: border-box;
  align-self: flex-start;
  line-height: 1.3 !important;
}
.container-right .right-title {
  font-family: 'utm-avo', Arial, sans-serif !important;
  font-size: 20px !important;
  margin: 8px 0;
  font-weight: 700;
  color: #000 !important;
}
.container-right .btn-print {
  display: block;
  width: 180px;     
  cursor: pointer;
  margin: 0 0 16px 0;
  background: none; 
  border: none;
}
.container-right .right-title {
  font-size: 16px;
  margin: 8px 0;
}

